const VERSION='1.2.51',CACHE='fz-host-next-'+VERSION;
const ASSETS=['./','./index.html','./style.css','./core.js','./transport.js','./communications.js','./app.js','./floor-alerts.js','./table-alerts.js','./voice-commands.js','./app-updates.js','./app-config.json','./manifest.webmanifest','./firebase-app-compat.js','./firebase-database-compat.js','./icon-192.png','./icon-512.png'].map(path=>/\.(js|css)$/.test(path)?path+'?v='+VERSION:path);
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS.map(url=>new Request(url,{cache:'reload'})))).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('fz-host-next-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request,{cache:'no-cache'}).then(r=>{if(r.ok&&!new URL(e.request.url).searchParams.has('update')){const copy=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,copy)));}return r;}).catch(async()=>{const cache=await caches.open(CACHE);return await cache.match(e.request)||(e.request.mode==='navigate'?await cache.match('./index.html'):null)||Response.error();}));});
